#!/usr/bin/env python3
"""Measure whether agents actually INVOKED given CLI subcommands, vs merely
having the strings appear in their transcripts.

The trap this script exists to avoid: if a UserPromptSubmit hook injects text
that *quotes* the commands you're measuring, every prompt contains them, so
`grep -c` reports ~100% false positives. Real invocations only count when the
command appears in shell *command position* inside a Bash tool_use input.

Usage:
    python3 agent_cmd_usage.py entire why "entire checkpoint search" "entire search"
    python3 agent_cmd_usage.py --hint "Entire is enabled for this repo" entire why
    python3 agent_cmd_usage.py --all-verbs entire        # census of every subcommand
"""
from __future__ import annotations
import argparse, glob, json, os, re, sys
from collections import defaultdict

# ---------------------------------------------------------------- transcripts
ROOTS = [
    "~/.claude/projects",           # Claude Code (incl. subagent transcripts)
    "~/.codex/sessions",
    "~/.gemini/tmp",
    "~/.opencode/storage",
    "~/.copilot/history-session-state",
    "~/.factory/sessions",
    "~/.pi/sessions",
]

def transcript_files(roots):
    out = []
    for r in roots:
        p = os.path.expanduser(r)
        if not os.path.isdir(p):
            continue
        for ext in ("jsonl", "json"):
            out += glob.glob(os.path.join(p, "**", f"*.{ext}"), recursive=True)
    return sorted(set(out))

# ------------------------------------------------- shell-command normalisation
HEREDOC = re.compile(r"<<-?\s*(['\"]?)([A-Za-z_][A-Za-z0-9_]*)\1")

def strip_heredocs(cmd: str) -> str:
    """Drop heredoc bodies: their lines are data, not commands."""
    lines, out, pending = cmd.split("\n"), [], None
    for ln in lines:
        if pending is not None:
            if ln.strip() == pending:
                pending = None
            continue
        out.append(ln)
        m = HEREDOC.search(ln)
        if m:
            pending = m.group(2)
    return "\n".join(out)

def mask_quotes(cmd: str) -> str:
    """Blank out quoted spans so prose inside --body '...' can't look like a
    command. Keeps the quotes themselves so arg structure survives."""
    out, i, n = [], 0, len(cmd)
    while i < n:
        ch = cmd[i]
        if ch in "'\"":
            j = cmd.find(ch, i + 1)
            if j == -1:
                out.append(cmd[i:]); break
            out.append(ch + " " * (j - i - 1) + ch)
            i = j + 1
        else:
            out.append(ch); i += 1
    return "".join(out)

SPLIT = re.compile(r"(?:\|\||&&|[;|\n])")
# leading noise before the real argv[0]
PREFIX = re.compile(
    r"^\s*(?:"
    r"[A-Za-z_][A-Za-z0-9_]*=\S*\s+"      # FOO=bar
    r"|(?:sudo|env|time|exec|nohup|command)\s+"
    r"|cd\s+\S+\s+"                        # cd x && ... survives the split, but be safe
    r"|\(\s*|\{\s*|then\s+|do\s+|else\s+"
    r")+"
)

def command_segments(cmd: str):
    """Yield each shell segment with leading noise stripped — i.e. things that
    are genuinely in command position."""
    for seg in SPLIT.split(strip_heredocs(mask_quotes(cmd))):
        seg = PREFIX.sub("", seg.strip())
        if seg:
            yield seg

# ------------------------------------------------------- transcript traversal
def bash_commands(rec):
    """Yield every string that a shell actually executed.

    Covers Claude Code's `Bash`, plus the equivalents other agent CLIs use, and
    ignores tool_result / assistant prose entirely (that is where the false
    positives live)."""
    msg = rec.get("message")
    containers = []
    if isinstance(msg, dict) and isinstance(msg.get("content"), list):
        containers = msg["content"]
    elif isinstance(rec.get("content"), list):        # codex-style flat records
        containers = rec["content"]
    for b in containers:
        if not isinstance(b, dict) or b.get("type") not in ("tool_use", "function_call"):
            continue
        name = (b.get("name") or "").lower()
        if name not in ("bash", "shell", "run_terminal_cmd", "execute_command",
                        "local_shell_call", "runcommand", "terminal"):
            continue
        inp = b.get("input") or b.get("arguments") or {}
        if isinstance(inp, str):
            try: inp = json.loads(inp)
            except Exception: inp = {"command": inp}
        for key in ("command", "cmd", "script", "shell_command"):
            v = inp.get(key)
            if isinstance(v, str):
                yield v
            elif isinstance(v, list):                 # codex: ["bash","-lc","..."]
                yield " ".join(str(x) for x in v)

# ------------------------------------------------------------------------ main
def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("targets", nargs="+",
                    help='e.g. entire why "entire checkpoint search"; first word is the binary')
    ap.add_argument("--hint", default=None,
                    help="substring of the injected context, to compute a denominator")
    ap.add_argument("--all-verbs", action="store_true",
                    help="also print a census of every <binary> subcommand invoked")
    ap.add_argument("--roots", nargs="*", default=ROOTS)
    ap.add_argument("--json", action="store_true")
    args = ap.parse_args()

    binary = args.targets[0].split()[0]
    # `entire checkpoint search` also matches the cp/checkpoints aliases
    ALIASES = {"checkpoint": ["checkpoint", "cp", "checkpoints"],
               "session": ["session", "sessions"]}
    targets = {}
    for t in args.targets:
        parts = t.split()
        if parts[0] == binary:
            parts = parts[1:]
        if not parts:
            continue
        heads = ALIASES.get(parts[0], [parts[0]])
        pats = [re.compile(r"^(?:\S*/)?" + re.escape(binary) + r"\s+(?:--?\S+\s+)*"
                           + r"\s+(?:--?\S+\s+)*".join(re.escape(p) for p in ([h] + parts[1:]))
                           + r"(?:\s|$)") for h in heads]
        targets[t] = pats

    VERB = re.compile(r"^(?:\S*/)?" + re.escape(binary) + r"\s+(?:--?\S+\s+)*([a-z][a-z0-9-]*)"
                      r"(?:\s+(?:--?\S+\s+)*([a-z][a-z0-9-]*))?")
    GROUPS = {"checkpoint","cp","checkpoints","session","sessions","agent","auth","doctor",
              "org","project","repo","grant","trail","mirror","labs"}

    files = transcript_files(args.roots)
    hits = defaultdict(list)
    verbs, verb_files = defaultdict(int), defaultdict(set)
    hint_files, hint_ts = set(), []
    n_lines = n_cmds = 0

    for f in files:
        try:
            raw = open(f, errors="replace").read()
        except OSError:
            continue
        has_hint = bool(args.hint) and args.hint in raw
        if has_hint:
            hint_files.add(f)
        for line in raw.splitlines():
            line = line.strip()
            if not line:
                continue
            n_lines += 1
            try:
                rec = json.loads(line)
            except Exception:
                continue
            if has_hint and args.hint in line and rec.get("timestamp"):
                hint_ts.append(rec["timestamp"])
            if binary not in line:
                continue
            for cmd in bash_commands(rec):
                if binary not in cmd:
                    continue
                n_cmds += 1
                for seg in command_segments(cmd):
                    for label, pats in targets.items():
                        if any(p.match(seg) for p in pats):
                            hits[label].append({
                                "ts": (rec.get("timestamp") or "")[:19],
                                "file": os.path.relpath(f, os.path.expanduser("~")),
                                "hint": has_hint, "cmd": seg[:200],
                            })
                    m = VERB.match(seg)
                    if m:
                        v = m.group(1)
                        if v in GROUPS and m.group(2):
                            v += " " + m.group(2)
                        verbs[v] += 1
                        verb_files[v].add(f)

    if args.json:
        json.dump({"scanned": {"files": len(files), "records": n_lines, "shell_calls": n_cmds},
                   "hits": hits, "verbs": dict(verbs),
                   "hint_files": len(hint_files)}, sys.stdout, indent=1)
        return

    print(f"scanned {len(files)} transcripts / {n_lines} records / "
          f"{n_cmds} shell calls mentioning {binary!r}\n")
    print("REAL INVOCATIONS (shell command position only)")
    for label in args.targets:
        hs = hits.get(label, [])
        print(f"  {len(hs):5d}  {label}")
        for h in hs[:10]:
            print(f"           {h['ts']}  {h['cmd']}")
    if args.hint:
        print(f"\nDENOMINATOR: {len(hint_files)} transcripts carried the injected hint", end="")
        if hint_ts:
            print(f" ({min(hint_ts)[:10]} .. {max(hint_ts)[:10]})")
        else:
            print()
    if args.all_verbs:
        print(f"\nCENSUS of every `{binary} <verb>` actually invoked:")
        for v in sorted(verbs, key=lambda x: -verbs[x]):
            print(f"  {verbs[v]:5d} calls / {len(verb_files[v])} files   {binary} {v}")

if __name__ == "__main__":
    main()

