import json, glob, os
from collections import Counter
# find which KEYS hold shell commands across every agent CLI, generically
keys = Counter()
def walk(o, path=""):
    if isinstance(o, dict):
        for k, v in o.items():
            if isinstance(v, str) and ("entire " in v or v.strip().startswith(("git ","ls ","cd "))) and len(v) < 3000:
                keys[k] += 1
            elif isinstance(v, list) and v and all(isinstance(x,str) for x in v) and any("entire " in x or x in ("bash","-lc","-c") for x in v):
                keys[k+"[]"] += 1
            walk(v, path+"/"+k)
    elif isinstance(o, list):
        for x in o: walk(x, path)

for root in ("~/.codex/sessions","~/.copilot","~/.factory","~/.gemini","~/.pi"):
    p=os.path.expanduser(root)
    if not os.path.isdir(p): continue
    fs=[f for f in glob.glob(p+"/**/*.jsonl",recursive=True)+glob.glob(p+"/**/*.json",recursive=True)]
    for f in fs[:400]:
        try: raw=open(f,errors="replace").read()
        except OSError: continue
        if "entire " not in raw: continue
        for line in raw.splitlines():
            line=line.strip()
            if not line: continue
            try: walk(json.loads(line))
            except Exception: pass
print("candidate command-bearing keys:")
for k,v in keys.most_common(25): print(f"  {v:6d}  {k}")
