213	// renderAgentHelpJSON renders the structured form of a command node.
214	func renderAgentHelpJSON(rootCmd, target *cobra.Command, repoLine string, trailsEnabled bool) (string, error) {
215		doc := agentHelpJSON{
216			Command: target.CommandPath(),
217			Short:   target.Short,
