279	// agentHelpRepoBlock formats the auto-detected repo line, degrading gracefully
280	// when the repo can't be resolved (no origin / detached HEAD) rather than
281	// implying a repo that isn't there.
282	func agentHelpRepoBlock(repoLine string) string {
283		// Defense-in-depth: this line is emitted as plain text into agent context and
284		// the user's terminal. A crafted origin URL's control characters (newline,
285		// ANSI escapes) are rejected upstream in gitremote, but never let one reach
286		// this plain-text sink — degrade to the not-detectable message instead.
287		if strings.TrimSpace(repoLine) == "" || strings.IndexFunc(repoLine, unicode.IsControl) >= 0 {
288			return "Current repo: not auto-detectable here (no origin remote / detached HEAD); pass --repo explicitly.\n"
289		}
290		return "Current repo: " + repoLine + "  (auto-detected from origin; pass --repo only for a DIFFERENT repo)\n"
291	}
