293	// renderAgentHelpCommand renders one resolved command node for an agent: its
294	// path + Short, its Long description, the auto-detected repo line, its live flag
295	// usages (hidden flags are skipped by cobra), and its advertised subcommands.
296	func renderAgentHelpCommand(cmd *cobra.Command, repoLine string, trailsEnabled bool) string {
297		var b strings.Builder
298		fmt.Fprintf(&b, "%s — %s\n", cmd.CommandPath(), cmd.Short)
299		if long := strings.TrimSpace(cmd.Long); long != "" && long != strings.TrimSpace(cmd.Short) {
300			b.WriteString(long)
301			b.WriteString("\n")
302		}
303		if example := strings.TrimSpace(cmd.Example); example != "" {
304			b.WriteString("\nExamples:\n")
305			b.WriteString(example)
306			b.WriteString("\n")
307		}
308		b.WriteString("\n")
309		b.WriteString(agentHelpRepoBlock(repoLine))
310	
311		// LocalFlags()/InheritedFlags() trigger cobra's persistent-flag merge (plain
312		// Flags() does not without Execute) and skip hidden flags in FlagUsages.
313		if usages := strings.TrimRight(cmd.LocalFlags().FlagUsages(), "\n"); usages != "" {
314			b.WriteString("\nFlags:\n")
315			b.WriteString(usages)
316			b.WriteString("\n")
317		}
318		if usages := strings.TrimRight(cmd.InheritedFlags().FlagUsages(), "\n"); usages != "" {
319			b.WriteString("\nInherited flags:\n")
320			b.WriteString(usages)
321			b.WriteString("\n")
322		}
323	
324		if subs := agentHelpCommands(cmd, trailsEnabled); len(subs) > 0 {
325			names := make([]string, 0, len(subs))
326			for _, sub := range subs {
327				names = append(names, sub.Name())
328			}
329			fmt.Fprintf(&b, "\nSubcommands: %s\n", strings.Join(names, " · "))
330			fmt.Fprintf(&b, "Next:  entire agent-help %s <subcommand>\n", strings.TrimPrefix(cmd.CommandPath(), cmd.Root().Name()+" "))
331		}
332		return b.String()
333	}
