	var drill agentHelpJSON
	if err := json.Unmarshal([]byte(raw), &drill); err != nil {
		t.Fatalf("unmarshal drill json: %v", err)
	}
	for _, sub := range drill.Subcommands {
		if sub.Audience != "" {
			t.Errorf("drill-down subcommand %q should omit audience, got %q", sub.Name, sub.Audience)
		}
	}
}
