// renderAgentHelpTop renders the top-level agent-facing overview: the curated
// intro + rule, the auto-detected repo line, the listed commands with their
// safety, a compact index of everything else, and the drill-down pointer.
//
// It lists a curated subset rather than the whole tree. An exhaustive listing
// answers "what exists?", which is not the question an agent mid-task has, and
// it grew past the length at which the listing gets read at all. Everything
// omitted here is still resolvable through `agent-help <command>` and named in
// the footer, so this trades default visibility, never availability.
func renderAgentHelpTop(rootCmd *cobra.Command, repoLine string, trailsEnabled bool) string {
	var b strings.Builder
	b.WriteString(agentHelpOverview)
	b.WriteString("\n\n")
	b.WriteString(agentHelpRepoBlock(repoLine))

	var listed []*cobra.Command
	var rest []string
	width := 10
	for _, sub := range agentHelpCommands(rootCmd, trailsEnabled) {
		if !agentHelpFactsFor(agentHelpPath(sub)).listed {
			rest = append(rest, sub.Name())
			continue
		}
		listed = append(listed, sub)
		if len(sub.Name()) > width {
			width = len(sub.Name())
		}
	}

	if len(listed) > 0 {
		b.WriteString("\nWhen to use entire — what bears on the work:\n")
		for _, sub := range listed {
			facts := agentHelpFactsFor(agentHelpPath(sub))
			fmt.Fprintf(&b, "  %-*s %s\n", width, sub.Name(), sub.Short)
			fmt.Fprintf(&b, "  %-*s   %s\n", width, "", agentHelpSafetyNote(sub, facts, trailsEnabled))
		}
	}
	if len(rest) > 0 {
		// Names only, no Short help: enough for an agent to connect a user's
		// request ("run a review") to a command, at a fraction of the lines the
		// full entries cost.
		b.WriteString("\nAlso available — setup, admin, and commands to run only when asked:\n")
		b.WriteString(wrapIndented(strings.Join(rest, " · "), "  ", 76))
		b.WriteString("\n  Suggest these; don't run them uninvited.\n")
	}

// wrapIndented soft-wraps a " · "-joined list at width, prefixing every line
// with indent. Keeps the footer index compact without letting a growing command
// set produce one very long line.
func wrapIndented(s, indent string, width int) string {
	var b strings.Builder
	line := indent
	for i, part := range strings.Split(s, " · ") {
		candidate := part
		if i > 0 {
			candidate = " · " + part
		}
		if len(line)+len(candidate) > width && line != indent {
			b.WriteString(line + "\n")
			line = indent + part
			continue
		}
		line += candidate
	}
	b.WriteString(line + "\n")
	return b.String()
}

